(() => {
 const node=document.getElementById('garden-effects-config');if(!node)return;const config=JSON.parse(node.textContent);
 for(const item of config.flash||[]){const box=document.getElementById(item.id);try{const player=window.RufflePlayer.newest().createPlayer();player.style.width='100%';player.style.height='100%';box.append(player);const style=document.createElement('style');style.textContent='#hardware-acceleration-modal{display:none!important}';player.shadowRoot?.append(style);const api=typeof player.ruffle==='function'?player.ruffle():player;api.load({url:item.url,allowScriptAccess:false,allowNetworking:'internal'}).then(()=>{box.dataset.loaded='true'}).catch(()=>{box.dataset.loaded='false';box.append(document.createTextNode('动画载入失败，请刷新后重试。'))})}catch{box.textContent='动画兼容播放器尚未加载，请刷新重试。'}}
 const running=[];let previous=0;const random=(a,b)=>a+Math.random()*(b-a);
 const load=asset=>new Promise(resolve=>{if(!asset?.available)return resolve(null);const image=new Image();image.crossOrigin='anonymous';image.onload=()=>resolve(image);image.onerror=()=>resolve(null);image.src=asset.url});
 function animate(step,canvas){running.push({step,canvas});}
 function snow(canvas,count=40,background){const ctx=canvas.getContext('2d'),flakes=Array.from({length:count},()=>({x:random(0,canvas.width),y:random(0,canvas.height),r:random(1,3),v:random(18,55),a:random(0,6.28)}));animate((time,dt)=>{ctx.clearRect(0,0,canvas.width,canvas.height);if(background)ctx.drawImage(background,0,0,canvas.width,canvas.height);ctx.fillStyle='#fff';for(const p of flakes){p.y=(p.y+p.v*dt)%(canvas.height+10);p.x=(p.x+Math.sin(time*.5+p.a)*12*dt+canvas.width)%canvas.width;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()}},canvas)}
 if(config.snow){const canvas=document.createElement('canvas');canvas.id='garden-snow';canvas.style.cssText='position:fixed;inset:0;width:100%;height:100%;pointer-events:none;z-index:100';canvas.width=innerWidth;canvas.height=innerHeight;document.body.append(canvas);addEventListener('resize',()=>{canvas.width=innerWidth;canvas.height=innerHeight});snow(canvas,12)}
 for(const item of config.applets){const box=document.getElementById(item.id),canvas=box?.querySelector('canvas');if(!canvas)continue;
  Promise.all(item.images.map(load)).then(images=>{const ctx=canvas.getContext('2d'),background=images[0],overlay=images[1];if(!background){const note=document.createElement('small');note.textContent='原图待补齐';note.style.cssText='display:block;color:inherit;font:12px sans-serif';box.append(note)}
   if(item.kind==='snow'){snow(canvas,100,background);return}
   const drops=Array.from({length:180},()=>({x:random(0,canvas.width),y:random(0,canvas.height),v:random(140,280)}));
   animate((time,dt)=>{ctx.clearRect(0,0,canvas.width,canvas.height);if(item.kind==='lake'){const h=canvas.height*.56;if(background){ctx.drawImage(background,0,0,canvas.width,h);for(let y=0;y<canvas.height-h;y+=2){const source=Math.max(0,background.height-1-y/(canvas.height-h)*background.height),shift=Math.sin(y*.12-time*3)*(1+y*.04);ctx.drawImage(background,0,source,background.width,1,shift,h+y,canvas.width,2)}if(overlay)ctx.drawImage(overlay,0,0,canvas.width,canvas.height)}}
    else if(item.kind==='fade'){const alpha=(Math.sin(time*.35)+1)/2;if(background){ctx.globalAlpha=1;ctx.drawImage(background,0,0,canvas.width,canvas.height)}if(overlay){ctx.globalAlpha=alpha;ctx.drawImage(overlay,0,0,canvas.width,canvas.height);ctx.globalAlpha=1}}
    else{if(background)ctx.drawImage(background,0,0,canvas.width,canvas.height);ctx.strokeStyle='#c0c5c8aa';ctx.lineWidth=1;ctx.beginPath();for(const p of drops){p.y+=p.v*dt;if(p.y>canvas.height){p.y=-15;p.x=random(0,canvas.width)}ctx.moveTo(p.x,p.y);ctx.lineTo(p.x-2,p.y+12)}ctx.stroke()}
   },canvas);
  });
 }
 if(config.fireworks){const canvas=document.getElementById('canvas')||document.body.appendChild(document.createElement('canvas'));canvas.width=800;canvas.height=507;canvas.style.cssText='display:block;max-width:100%;height:auto;margin:auto;touch-action:manipulation;background:#000';canvas.dataset.gardenEffect='fireworks';const ctx=canvas.getContext('2d'),particles=[];let bg=null;load(config.fireworkImage).then(image=>bg=image);
  const sounds=(config.fireworkSounds||[]).map(a=>a.available?new Audio(a.url):null);if(sounds[2])sounds[2].loop=true;const play=n=>{const a=sounds[n];if(a){a.currentTime=0;a.play().catch(()=>{})}};
  canvas.addEventListener('pointerdown',ev=>{const bounds=canvas.getBoundingClientRect(),x=(ev.clientX-bounds.left)*800/bounds.width,y=Math.min(265,(ev.clientY-bounds.top)*507/bounds.height),hue=random(0,360);for(let i=0;i<150;i++){const a=random(0,Math.PI*2),v=random(20,155);particles.push({x,y:270,target:y,launch:true,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:random(1.2,2.4),color:`hsl(${hue} 100% 65%)`})}canvas.dataset.bursts=String(Number(canvas.dataset.bursts||0)+1);play(0);if(sounds[2]?.paused)play(2)});
  animate((time,dt)=>{ctx.fillStyle='rgba(0,0,0,.22)';ctx.fillRect(0,0,800,507);if(bg)ctx.drawImage(bg,0,270,800,237);let exploded=false;for(let i=particles.length-1;i>=0;i--){const p=particles[i];if(p.launch){p.y-=260*dt;if(p.y<=p.target){p.launch=false;exploded=true}}else{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=38*dt}if(p.life<=0||p.y>270&&!p.launch){particles.splice(i,1);continue}ctx.fillStyle=p.launch?'#fff':p.color;ctx.fillRect(p.x,p.y,p.launch?1:2,p.launch?5:2)}if(exploded)play(1)},canvas);
 }
 function frame(stamp){const dt=Math.min(.05,(stamp-previous)/1000||.016);previous=stamp;if(!document.hidden)for(const item of running){item.step(stamp/1000,dt);item.canvas.dataset.frames=String(Number(item.canvas.dataset.frames||0)+1)}requestAnimationFrame(frame)}requestAnimationFrame(frame);
 if(config.missing?.length){const note=document.createElement('p');note.id='garden-effects-missing';note.textContent='此页部分原始特效素材尚待补齐。';note.style.cssText='text-align:center;font:12px sans-serif;opacity:.7';document.body.append(note)}
})();
